[Form]
public class TFMListEditor extends FormRun
{
    TFMListEditorTree	listTree;
    TFMList			    currentList;
    TFMListsVersion		currentListVersion;

    Map				list2Pages;
    QueryBuildRange qbrPageId;
}

public void updateVisual()
{
    TFMListVisualization::DrawList(PreviewWindow,currentList.parmListName(),currentListVersion,DrawCells.value(),DrawDevice.value(),UseDataset.value() ? TFMPageDatasources : null);
    element.refreshXmlOutput();
}

public void run()
{

    super();

    TFMLists = element.args().record();
    listTree = TFMListEditorTree::Construct(DesignTree,attributeGroup,TreenodeButtons, element, TFMPageDatasources);
    currentList = TFMListsProvider::getAllLists().getList(TFMLists.ListId);
    TFMLists_TFMListId.text(currentList.parmListName());
    TFMLists_TFMListId.modified();

    if(currentList.parmDeltaLevel() == TFMDeltaLevel::Code)
    {
        TFMListConfiguration listConf = currentList.getList(); // since it is coming from code we call the getList directly.
        TFMListsVersion_displayStatus.dataSource(null);
        TFMListsVersion_useSingleSelection.dataSource(null);
        TFMListsVersion_useSingleSelection.value(listConf.parmUseSingleSelection());
        TFMListsVersion_displayStatus.value(listConf.parmDisplayStatus());

        //disable the buttons because they can only be changed when a version exists.
        TFMListsVersion_displayStatus.enabled(false);
        TFMListsVersion_useSingleSelection.enabled(false);

    }

    element.updateDataSource();
    this.updateVisual();

    TabXML.visible(TFMParameters::find().DeveloperMode);
}

public void updateDataSource()
{
    MapEnumerator	pageMap;
    TFMPages		pages;
    TFMPage			page;
    TFMListId		listId;

    list2Pages = new Map(Types::String, Types::String);

    pageMap = TFMPagesProvider::getAllPages().getPages().getEnumerator();
    while (pageMap.moveNext())
    {
        page = pageMap.currentValue();
        listId = page.getListId();
        if (listId)
        {
            list2Pages.insert(listId,(list2Pages.exists(listId) ? list2Pages.lookup(listId) + ',' : '') + page.parmId());
        }
    }
    qbrPageId = TFMPageDatasources_DS.queryBuildDataSource().addRange(fieldNum(TFMPageDatasources,Pageid));
    qbrPageId.value(list2Pages.exists(currentList.parmListName()) ? list2Pages.lookup(currentList.parmListName()) : 'nonExistingPage');
    TFMPageDatasources_ds.executeQuery();
}

/// <summary>
/// Updates the datasource used for the TFMListVerion datasource. The verison is provided because it might change with the versions combobox.
/// </summary>
/// <param name = "_version"></param>
protected void updateTFMVersionsDatasource(Version _version)
{
    if(currentList.parmDeltaLevel() == TFMDeltaLevel::Code)
    {
        TFMListsVersionDS_DS.allowCreate(false);
        TFMListsVersionDS_DS.allowEdit(false);
        TFMListsVersionDS_DS.allowDelete(false);
        return;
    }
    QueryBuildRange qbrVersion;
    qbrVersion = TFMListsVersionDS_ds.queryBuildDataSource().addRange(fieldNum(TFMListsVersion, ListId));
    qbrVersion.value(currentList.parmListName());

    qbrVersion = TFMListsVersionDS_ds.queryBuildDataSource().addRange(fieldNum(TFMListsVersion, Version));
    qbrVersion.value(VersionsAvailable.valueStr() ? VersionsAvailable.valueStr() : '0');

    TFMListsVersionDS_DS.executeQuery();

    currentListVersion = TFMListsVersionDS;

    if(TFMListsVersionDS.Locked)
    {
        TFMListsVersionDS_DS.allowCreate(false);
        TFMListsVersionDS_DS.allowEdit(false);
    }

    TFMListsVersionDS_DS.allowDelete(false); // never delete
}

 public void updateListTree(str _version, int _curListIdx)
 {
     RecId selectedRecId = listTree.currentSelectedRecId();

     TFMListID currentListId = currentList.parmListName();
     DesignTree.deleteAll();
     int currentListVer = str2Int(_version);

     listTree.buildTree(currentListId, currentListVer);
     if(_curListIdx > 0)
     {
         listTree.setSelection(selectedRecId);
     }


}

protected void refreshXmlOutput()
{
    if(!XmlViewer.isVisible() )
    {
        return;
    }
    XML outputXmlStr;
    XmlElement outputElement;

    outputElement = XmlDocument::newBlank().createElement('output');

    currentList.appendToXML(outputElement, currentListVersion, !FormCheckBoxControl_ShowExportFormat.value());

    XmlViewer.parmFormatAsXml('Yes');
    XmlViewer.parmHtml(TFMFormXMLFormatter::htmlColorXML( outputElement.xml()));
}

/// <summary>
///
/// </summary>
public void write()
{
    if(TFMListsVersionDS_DS.allowEdit())
    {
        RecId curRecId = listTree.currentSelectedRecId();
        super();
        element.updateListTree(VersionsAvailable.valueStr(), curRecId);
    }
}

/// <summary>
///
/// </summary>
public void refresh()
{
    RecId curRecId = listTree.currentSelectedRecId();
    super();
    element.updateListTree(VersionsAvailable.valueStr(), curRecId);
}

public int active()
{
    int ret = super();
    if (UseDataset.value())
    {
        element.updateVisual();
    }


    return ret;
}

