public void selectionChanged(FormTreeItem _OldItem, FormTreeItem _NewItem, FormTreeSelect _how)
{
    super(_OldItem, _NewItem, _how);
    listTree.selectionChanged(_OldItem, _NewItem, _how);
}

public boolean modified()
{
    boolean ret;
    TFMListsVersion versions;
    ret = super();

    TFMListID currentListId = this.text();
    currentList = TFMListsProvider::getAllLists().getList(currentListId);
    currentListVersion = TFMListsVersion::newestVersion(currentListId, false);
    VersionsAvailable.clear();
    while select versions order by Version desc where versions.ListId == currentListId
    {
        VersionsAvailable.add(int2Str(versions.Version));
    }
    element.updateTFMVersionsDatasource(currentListVersion.Version);
    element.updateListTree(VersionsAvailable.valueStr(), 0);
    element.updateVisual();

    return ret;
}

public boolean modified()
{
    boolean ret;

    ret = super();

    currentListVersion = TFMListsVersion::Find(currentList.parmListName(), str2Int(this.valueStr()) );
    element.updateTFMVersionsDatasource(currentListVersion.Version);
    element.updateListTree(this.valueStr(), 0);
    element.updateVisual();
    return ret;
}

